import React, { useState } from 'react'
import styled from 'styled-components'
import { themeUFC } from 'theme/theme'
import EyeIcon from 'public/static/signup/eye.svg'
import PasswordRequirements from '../PasswordRequirements'
import TextInput from '../../TextInput'

const PasswordWrapper = styled.div`
	display: flex;
	flex-direction: column;
	margin-bottom: 19px;
`

const InputWrapper = styled.div`
	position: relative;
`

const ShowPasswordToggle = styled.button`
	position: absolute;
	right: 10px;
	top: 50%;
	transform: translateY(-50%);
	background: transparent;
	border: none;
	cursor: pointer;
	height: 24px;
	width: 24px;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 0;
	cursor: pointer;
	&[data-active='true'] {
		svg {
			path {
				fill: ${themeUFC.colors.primaryMidnight.toString()};
			}
		}
	}
`

const PasswordRequiremenetsWrapper = styled.div`
	margin-top: 16px;
	margin-left: 6px;
`

const Error = styled.div`
	margin-top: 8px;
`

interface IProps { 
	showPasswordRequirements: boolean
	value?: string
	onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void
	setIsPasswordValid?: (isPasswordValid: boolean) => void
	onKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void
	error?: string | null
}

const PasswordInput = (props: IProps) => {
	const { showPasswordRequirements, value, error, onChange, setIsPasswordValid, onKeyDown } = props
	const [showPassword, setShowPassword] = useState(false)
	return (
		<PasswordWrapper>
			<InputWrapper>
				<TextInput
					name="password"
					type={showPassword ? 'text' : 'password'}
					placeholder="Enter your new password"
					value={value}
					onInputChange={onChange}
					noMargin
					onKeyDown={onKeyDown}
				/>
				<ShowPasswordToggle onClick={() => setShowPassword(!showPassword)} data-active={showPassword}>
					<EyeIcon />
				</ShowPasswordToggle>
			</InputWrapper>
			{error && (
				<Error>
					<div className='ant-form-item-explain-error'>
						{error}
					</div>
				</Error>
			)}
			{showPasswordRequirements && (
				<PasswordRequiremenetsWrapper>
					<PasswordRequirements 
						value={value || ''}
						setIsPasswordValid={setIsPasswordValid}
					/>
				</PasswordRequiremenetsWrapper>
			)}
		</PasswordWrapper>
	)
}

export default PasswordInput