import React, { useEffect } from 'react'
import styled from 'styled-components'
import CheckmarkIcon from 'public/static/signup/checkmark.svg'
import ExclamationIcon from 'public/static/signup/explanation-mark.svg'
import { themeUFC } from 'theme/theme'
import { lengthRegex, uppercaseRegex, specialCharacterRegex, lowercaseRegex, digitRegex } from '..'

const Wrapper = styled.div`
	display: flex;
	flex-direction: column;
	gap: 21px;
`

const Row = styled.div`
	display: flex;
	gap: 4px;
	margin-left: 4px;
	font-family: 'Roboto', sans-serif;
	font-weight: 400;
	font-size: 14px;
	line-height: 100%;
	letter-spacing: 0%;
	vertical-align: middle;
	color: ${ themeUFC.colors.success500.toString() };
	align-items: center;
	transition: color 0.1s ease-in-out;
	&[aria-invalid="true"] {
		color: ${ themeUFC.colors.surface300.toString() };
	}
	svg {
		transition: opacity 0.2s ease-in-out, transform 0.2s ease-in-out;
		transform: scale(1.4);
	}
`

const PasswordRequirements = ({ value, setIsPasswordValid }: { value: string, setIsPasswordValid?: (isPasswordValid: boolean) => void }) => {
	const lengthValid = lengthRegex.test(value)
	const uppercaseValid = uppercaseRegex.test(value)
	const specialCharacterValid = specialCharacterRegex.test(value)
	const lowercaseValid = lowercaseRegex.test(value)
	const digitValid = digitRegex.test(value)

	useEffect(() => {
		if (setIsPasswordValid) {
			setIsPasswordValid(lengthValid && uppercaseValid && specialCharacterValid && digitValid && lowercaseValid)
		}
	}, [lengthValid, uppercaseValid, specialCharacterValid, digitValid, lowercaseValid, setIsPasswordValid])

	return (
		<Wrapper>
			<Row aria-invalid={!lengthValid}>
				{ lengthValid ? <CheckmarkIcon /> : <ExclamationIcon /> }
				Must be 12 characters
			</Row>
			<Row aria-invalid={!uppercaseValid}>
				{ uppercaseValid ? <CheckmarkIcon /> : <ExclamationIcon /> }
				Include at least an uppercase letter
			</Row>
			<Row aria-invalid={!specialCharacterValid}>
				{ specialCharacterValid ? <CheckmarkIcon /> : <ExclamationIcon /> }
				Include at least a special character
			</Row>
			<Row aria-invalid={!digitValid}>
				{ digitValid ? <CheckmarkIcon /> : <ExclamationIcon /> }
				Include at least one digit
			</Row>
			<Row aria-invalid={!lowercaseValid}>
				{ lowercaseValid ? <CheckmarkIcon /> : <ExclamationIcon /> }
				Include at least a lowercase letter
			</Row>
		</Wrapper>
	)
}

export default PasswordRequirements