import React, { useState } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'
import { IReduxState } from 'types/reduxStateTypes'
import { axiosInstance } from 'services/globalInstance'
import { SectionHeader } from 'components/features/onboard/FlowScreens/common'
import { rollbar } from 'components/common/rollbar'
import styled from 'styled-components'
import { useRouter } from 'next/router'
import { InfoBox } from '../SignupSecondaryLayout'
import PasswordInput from './PasswordInput'
import FlowLayout from '../FlowLayout'
import FlowNavButtons from '../FlowNavButtons'

const Wrapper = styled.div`
	display: flex;
	flex-direction: column;
	width: 100%;
	margin-bottom: 8px;
`

export const ErrorText = styled.p`
  font-size: 14px !important;
  color: #f4584c !important;
  text-align: left !important;
`

export const lengthRegex = /^.{12,}$/
export const uppercaseRegex = /[A-Z]/
export const specialCharacterRegex = /[!@#$%^&*-]/
export const lowercaseRegex = /[a-z]/
export const digitRegex = /[0-9]/

const SetupPassword = () => {
	const [value, setValue] = useState('')
	const [passwordError, setPasswordError] = useState<string | null>(null)
	const [errorMessage, setErrorMessage] = useState<string | null>(null)
	const [showPasswordRequirements, setShowPasswordRequirements] = useState(false)
	const { applicationReducer, profileReducer } = useSelector((state: IReduxState) => state)
	const dispatch = useDispatch()
	const orgName = applicationReducer[0]?.name
	const email = profileReducer?.email
	const router = useRouter()
	const [loading, setLoading] = useState(false)

	React.useEffect(() => {
		dispatch(trackPageViews(null, {
			eventName: 'wa_screenvisit_setup_create_password'
		}))
	}, [dispatch])
	
	const handleSubmit = async () => {
		setErrorMessage(null)
		
		if (!lengthRegex.test(value) || !uppercaseRegex.test(value) || !specialCharacterRegex.test(value) || !lowercaseRegex.test(value) || !digitRegex.test(value)) {
			if (!value?.length) {
				setPasswordError('This field is required')
			}else{
				setPasswordError('Your password needs to meet all the conditions below')
				setShowPasswordRequirements(true)
			}
			(document.querySelector('input[name="password"]') as HTMLInputElement)?.focus()
			return
		}

		setLoading(true)
		await axiosInstance
		.put(`${process.env.AUTH_API_URL}/user/create-password`, {
			password: value,
		}, {
			withCredentials: true,
		})
		.then(async (res) => {
			if ( res.status === 200 ) {
					await dispatch(trackPageViews(null, {
						eventName: 'wa_setup_password_created',
						eventProperty: {
							email: email || '',
							orgName: orgName || '',
							orgId: applicationReducer[0]?.orgId || '',
						}
					}));
					router.push(`/welcome/first_visit`)
				}
			})
			.catch((err) => {
				rollbar.error('Failed to set password', err)
				setErrorMessage('Failed to set password')
				setLoading(false)
			})
	}

	const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		if (e.target.value?.length) {
			setShowPasswordRequirements(true)
		} else {
			setShowPasswordRequirements(false)
		}
		setValue(e.target.value)
		setErrorMessage(null)
		setPasswordError(null)
	}

	const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
		if (e.key === 'Enter') {
			handleSubmit()
		}
	}

	return (
		<FlowLayout
			title="Create password"
			subTitle="Please choose a secure password to complete the setup."
			hideLogos
			progress={50}
			progressColor='green'
		>
			<Wrapper>
				<SectionHeader>
					Create a password
				</SectionHeader>
				<PasswordInput
					showPasswordRequirements={showPasswordRequirements}
					error={passwordError}
					value={value}
					onChange={handleInputChange}
					onKeyDown={handleKeyDown}
				/>
				{errorMessage && (
					<ErrorText>
						{errorMessage}
					</ErrorText>
				)}
			</Wrapper>
			<FlowNavButtons
				primaryText="Create account"
				loading={loading}
				primaryHandler={handleSubmit}
			/>
		</FlowLayout>
	)
}

export default SetupPassword
